/* Online-Wetter: Standard ist automatischer Abruf. Manuelle Eingabe nur als Korrektur/Fallback. */
function fp105WeatherDesc(code){const m={0:'klar',1:'überwiegend klar',2:'teilweise bewölkt',3:'bedeckt',45:'Nebel',48:'Raureifnebel',51:'leichter Nieselregen',53:'Nieselregen',55:'starker Nieselregen',56:'gefrierender Nieselregen',57:'starker gefrierender Nieselregen',61:'leichter Regen',63:'Regen',65:'starker Regen',66:'gefrierender Regen',67:'starker gefrierender Regen',71:'leichter Schneefall',73:'Schneefall',75:'starker Schneefall',77:'Schneegriesel',80:'leichte Regenschauer',81:'Regenschauer',82:'starke Regenschauer',85:'leichte Schneeschauer',86:'starke Schneeschauer',95:'Gewitter',96:'Gewitter mit Hagel',99:'starkes Gewitter mit Hagel'};return m[Number(code)]||`Wettercode ${code}`}
function fp105WindDir(deg){if(deg==null||!Number.isFinite(Number(deg)))return'';const p=['N','NNO','NO','ONO','O','OSO','SO','SSO','S','SSW','SW','WSW','W','WNW','NW','NNW'];return p[Math.round(Number(deg)/22.5)%16]}
function fp105Set(id,v){const e=document.getElementById(id);if(e&&v!=null&&!Number.isNaN(v))e.value=v}
