      const j=await fp105FetchJson(url),h=j.hourly||{},times=h.time||[];if(!times.length)throw new Error('Für diesen Zeitpunkt sind keine Online-Wetterdaten verfügbar.');let idx=0,best=Infinity;for(let i=0;i<times.length;i++){const delta=Math.abs(new Date(times[i]+'Z')-target);if(delta<best){best=delta;idx=i}}d={temp:h.temperature_2m?.[idx],hum:h.relative_humidity_2m?.[idx],press:h.surface_pressure?.[idx],wind:h.wind_speed_10m?.[idx],windDeg:h.wind_direction_10m?.[idx],gust:h.wind_gusts_10m?.[idx],cloud:h.cloud_cover?.[idx],rain:h.precipitation?.[idx],code:h.weather_code?.[idx],vis:h.visibility?.[idx]!=null?Number(h.visibility[idx])/1000:null};
